window.kbPageData["views/entry/k-856a5094ee72c642"] = {"key":"entry/k-856a5094ee72c642","state":{"route":"entry/k-856a5094ee72c642"},"node":{"id":"k-856a5094ee72c642","mode":"k","title":"同一违法行为不得重复罚款","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["同一违法行为不得给予两次以上罚款"],"qs":["国考 2024 行政执法 行测#11"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"行政机关对当事人的同一个违法行为，不得给予两次以上罚款。同一个违法行为违反多个法律规范且应当给予罚款时，按照罚款数额高的规定处罚。","review":{"definition":"行政机关对当事人的同一个违法行为，不得给予两次以上罚款。同一个违法行为违反多个法律规范且应当给予罚款时，按照罚款数额高的规定处罚。","explanation":"C项明示某公司因某一次违规代开发票被罚款三次，三次罚款针对同一个违法行为，违反《行政处罚法》第二十九条。","references":[],"evidence":"对当事人的同一个违法行为，不得给予两次以上罚款的行政处罚","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 行政执法 行测#11":{"paper":"国考 2024 行政执法 行测","n":11,"mod":"常识判断","src":["dfddc59dc6e7d9da5d71.pdf",2],"asrc":["6493f3a6a55c38431852.pdf",4],"card":"09c18159a03e15fe052d6091","links":[{"id":"k-856a5094ee72c642","role":"直接考查","why":"对同一次违法行为禁止重复罚款，涉及多个罚款规范时按罚款数额高的规定处罚。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-856a5094ee72c642":[["国考 2024 行政执法 行测#11"]]}};
